    function eCr(obj) {
        const s = encodeURIComponent(JSON.stringify(obj));
        const b = new Uint8Array(s.length);
        for (let i = 0; i < s.length; i++) b[i] = s.charCodeAt(i) ^ CRYPTO_KEY.charCodeAt(i % CRYPTO_KEY.length);
        let bin = ''; for (let i = 0; i < b.length; i++) bin += String.fromCharCode(b[i]);
        return btoa(bin).split('').reverse().join('');
    }
    function dCr(str) {
        try {
            const bin = atob(str.split('').reverse().join(''));
            const b = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) b[i] = bin.charCodeAt(i);
            let s = ''; for (let i = 0; i < b.length; i++) s += String.fromCharCode(b[i] ^ CRYPTO_KEY.charCodeAt(i % CRYPTO_KEY.length));
            return JSON.parse(decodeURIComponent(s));
        } catch { return null; }
    }
    function safe(str) { return String(str||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

    const _rl = {};
    function rl(k,max,ms){ const n=Date.now(); if(!_rl[k]||n>_rl[k].r){_rl[k]={c:1,r:n+ms};return true;} if(_rl[k].c>=max)return false; _rl[k].c++;return true; }

    const chunkBufs = {};
    function feedChunk(raw) {
        if(!raw?.cid||typeof raw.i!=='number'||typeof raw.t!=='number')return null;
        if(raw.t>10||raw.i>=raw.t||raw.i<0)return null;
        if(!chunkBufs[raw.cid]){chunkBufs[raw.cid]=new Array(raw.t).fill(null);setTimeout(()=>delete chunkBufs[raw.cid],15000);}
        const buf=chunkBufs[raw.cid]; if(!buf||buf.length!==raw.t)return null;
        buf[raw.i]=raw.p; if(buf.filter(p=>p!==null).length!==raw.t)return null;
        try{const r=JSON.parse(buf.join(''));delete chunkBufs[raw.cid];return r;}catch{return null;}
    }

    const isMobile = /Android|iPhone|iPad|iPod|Opera Mini|IEMobile|WPDesktop/i.test(navigator.userAgent) || window.innerWidth < 768;

    let idb = null;
    async function initIDB() {
        return new Promise((res) => {
            const req = indexedDB.open('garticpro', 2);
            req.onupgradeneeded = e => {
                const db = e.target.result;
                if (!db.objectStoreNames.contains('messages')) {
                    const store = db.createObjectStore('messages', { keyPath: 'id' });
                    store.createIndex('room', 'room', { unique: false });
                }
            };
            req.onsuccess = e => { idb = e.target.result; res(idb); };
            req.onerror = () => res(null);
        });
    }

    async function idbSave(msg) {
        if (!idb) return;
        try {
            const tx = idb.transaction('messages', 'readwrite');
            tx.objectStore('messages').put(msg);
            const all = await new Promise(r => { const req = tx.objectStore('messages').getAllKeys(); req.onsuccess = () => r(req.result); });
            if (all.length > 5000) {
                const toDelete = all.slice(0, all.length - 5000);
                toDelete.forEach(k => tx.objectStore('messages').delete(k));
            }
        } catch {}
    }

    async function idbGetRoom(room, limit = 200) {
        if (!idb) return [];
        return new Promise(res => {
            try {
                const tx = idb.transaction('messages', 'readonly');
                const idx = tx.objectStore('messages').index('room');
                const req = idx.getAll(room);
                req.onsuccess = () => res((req.result || []).slice(-limit));
                req.onerror = () => res([]);
            } catch { res([]); }
        });
    }

    const getCroxyIPs = (Q,u='https://www.croxyproxy.com')=>new Promise(async(r,w)=>{
        try{let c=Q||await new Promise(r2=>GM_xmlhttpRequest({method:"GET",url:u,withCredentials:0,anonymous:1,onload:x=>{try{r2(x.responseXML.forms[0][2].value);}catch{r2(null);}}}));
        if(!c)return w('csrf');
        GM_xmlhttpRequest({method:"POST",url:u+'/servers',headers:{'Content-Type':'application/x-www-form-urlencoded'},data:`url=&csrf=${c}`,
        onload:x=>{try{r(JSON.parse(x.responseXML.scripts[1].dataset.ss).flatMap(s=>{const hex=atob(s),bytes=new Uint8Array(hex.length/2);for(let i=0;i<hex.length;i+=2)bytes[i/2]=parseInt(hex.substring(i,i+2),16);const text=new TextDecoder().decode(bytes);const match=text.match(/(\d+\.){3}\d+/);return match?{ip:match[0]}:[];}));}catch{r([]);}},onerror:w});}catch(e){w(e);}
    });
    const getCSRF=(u='https://www.croxyproxy.com')=>new Promise((r,w)=>GM_xmlhttpRequest({method:"GET",url:u,withCredentials:0,anonymous:1,onload:x=>{try{r(x.responseXML?.forms[0]?.[2]?.value||null);}catch{w();}},onerror:w}));
    const getActivationCookie=(Q,w,y)=>new Promise(r=>GM_xmlhttpRequest({method:"GET",url:`https://${Q}/__cpi.php?s=${encodeURIComponent(w)}&r=${encodeURIComponent(btoa(`https://${Q}/server?__cpo=${btoa(y)}`))}&__cpo=1`,onloadend:x=>{let c=(x.responseHeaders.match(/set-cookie:\s*__cpc=([^;\r\n]+)/i)||[])[1];r(c||null);}}));

    class GSocket {
        constructor(url){this.url=url;this.ws=null;this.connected=false;this._ev={};this._acks={};this._aid=0;this._ret=0;this.connect();}
        connect(){
            this.ws=new WebSocket(this.url);
            this.ws.onopen=()=>{this._ret=0;setStatus('online');};
            this.ws.onmessage=e=>{
                const msg=e.data; if(typeof msg!=='string')return;
                const et=msg[0],ed=msg.substring(1);
                if(et==='0')this.ws.send('40');
                else if(et==='2')this.ws.send('3');
                else if(et==='4'){
                    const st=ed[0],sd=ed.substring(1);
                    if(st==='0'){this.connected=true;this._emit('connect');}
                    else if(st==='2'){const m=sd.match(/^(\d+)?(\[[\s\S]*\])$/);if(m?.[2])try{const p=JSON.parse(m[2]);this._emit(p[0],p[1]);}catch{}}
                    else if(st==='3'){const m=sd.match(/^(\d+)([\s\S]*)$/);if(m&&this._acks[m[1]]){try{this._acks[m[1]](m[2]?JSON.parse(m[2])[0]:null);}catch{}delete this._acks[m[1]];}}
                }
            };
            this.ws.onclose=()=>{this.connected=false;this._emit('disconnect');setStatus('connecting');this._ret++;setTimeout(()=>this.connect(),Math.min(1000*Math.pow(2,this._ret),30000));};
            this.ws.onerror=()=>setStatus('offline');
        }
        on(ev,fn){if(!this._ev[ev])this._ev[ev]=[];this._ev[ev].push(fn);}
        send(ev,data,cb){
            if(!this.ws||this.ws.readyState!==1)return;
            let pkt='42'; if(typeof cb==='function'){this._aid++;this._acks[this._aid]=cb;pkt+=this._aid;}
            pkt+=JSON.stringify(data!==undefined?[ev,data]:[ev]); this.ws.send(pkt);
        }
        _emit(ev,data){(this._ev[ev]||[]).forEach(fn=>fn(data));}
    }

    let socket=null, serverURL='';
    let token=localStorage.getItem('gc_token')||'';
    let deviceId=localStorage.getItem('gc_dev')||((()=>{const id='dev_'+Math.random().toString(36).substr(2,9)+Date.now().toString(36);localStorage.setItem('gc_dev',id);return id;})());
    let currentRoom='',myName='',myRole=1,myLevel=1,myTitle='Standard Node',myXp=0;
    let myStreak=0,myMult=1.0;
    let pendingAcks={},onlineUsers=[],dmTarget='';
