    let replyToId=null,mentionIndex=-1,typingTimer=null;
    let searchActive=false,searchQuery='';
    let gameStateTimer=null;
    let globalJoined=false; // FIX: global duplicate bug

    try {
        const res = await new Promise((ok,fail)=>GM_xmlhttpRequest({method:'GET',url:'https://limegreen-wolverine-863744.hostingersite.com/link.php?auth=tampermonkey',onload:r=>{try{ok(JSON.parse(r.responseText));}catch{fail();}},onerror:fail}));
        if(res.status==='success'&&/^https:\/\/[a-zA-Z0-9-]+\.trycloudflare\.com/.test(res.url)) serverURL=res.url;
        else throw new Error();
    } catch { console.error('[GP] PHP fail'); return; }

    await initIDB();

    // ── HOST — pointer-events transparent kaplıyor her şeyi
    const host = document.createElement('div');
